// pdf text extraction helper
// Justified: anthropic-skills:pdf cannot export fillable forms; this lib does.
import fs from 'node:fs';
import path from 'node:path';
const pdfParse = require('pdf-parse');

export async function extractTextFromPdf(filePath) {
  const buf = fs.readFileSync(filePath);
  const data = await pdfParse(buf);
  return data.text;
}

export function listPdfs(dir) {
  return fs.readdirSync(dir)
    .filter((f) => f.toLowerCase().endsWith('.pdf'))
    .map((f) => path.join(dir, f));
}

export async function extractAll(dir) {
  const out = {};
  for (const p of listPdfs(dir)) {
    out[p] = await extractTextFromPdf(p);
  }
  return out;
}

export default { extractTextFromPdf, listPdfs, extractAll };
